    23	  if (!definition) return false;
    24	
    25	  if (definition.overridable && ctx.overrides?.includes(flag)) {
    26	    return true;
    27	  }
    28	
    29	  const strategy = definition.strategy;
    30	  switch (strategy.kind) {
    31	    case "off":
    32	      return false;
    33	    case "on":
