    29	/** Reads a string prop defensively — templates are fed loosely typed payloads. */
    30	function str(props: Props, key: string, fallback = ""): string {
    31	  const value = props[key];
    32	  return typeof value === "string" && value !== "" ? value : fallback;
    33	}
    34	
    35	function count(props: Props, key: string): number {
    36	  const value = props[key];
