    50	    case "welcome":
    51	      return createElement(WelcomeEmail, props as unknown as WelcomeEmailProps);
    52	    case "password-reset":
    53	      return createElement(
    54	        PasswordResetEmail,
    55	        props as unknown as PasswordResetEmailProps,
    56	      );
    57	    case "overdue":
    58	      return createElement(OverdueEmail, props as unknown as OverdueEmailProps);
    59	  }
    60	}
    61	
    62	/** The subject line for a template, derived from the same props as the body. */
    63	export function subjectFor(template: EmailTemplate, props: Props): string {
    64	  switch (template) {
    65	    case "invite":
    66	      return `${str(props, "inviterName", "Someone")} invited you to ${str(
    67	        props,
    68	        "orgName",
    69	        SITE_CONFIG.name,
    70	      )}`;
    71	    case "digest": {
    72	      const total = count(props, "entries");
    73	      return `Your ${str(props, "orgName", SITE_CONFIG.name)} digest — ${total} update${
    74	        total === 1 ? "" : "s"
    75	      }`;
    76	    }
    77	    case "mention":
    78	      return `${str(props, "actorName", "Someone")} mentioned you on "${str(
    79	        props,
    80	        "issueTitle",
    81	        "an issue",
    82	      )}"`;
    83	    case "invoice":
    84	      return `Invoice ${str(props, "invoiceNumber", "")} for ${str(
    85	        props,
    86	        "orgName",
    87	        SITE_CONFIG.name,
    88	      )}`.replace(/\s+/g, " ");
    89	    case "welcome":
    90	      return `Welcome to ${SITE_CONFIG.name}`;
    91	    case "password-reset":
    92	      return `Reset your ${SITE_CONFIG.name} password`;
    93	    case "overdue": {
    94	      const total = count(props, "issues");
    95	      return `${total} overdue issue${total === 1 ? "" : "s"} in ${SITE_CONFIG.name}`;
    96	    }
    97	  }
    98	}
    99	
   100	/** Renders both the HTML and the plain-text alternative in one pass. */
   101	export async function renderTemplate(
   102	  template: EmailTemplate,
   103	  props: Props,
   104	): Promise<RenderedEmail> {
   105	  const element = elementFor(template, props);
   106	  const [html, text] = await Promise.all([
   107	    render(element),
   108	    render(element, { plainText: true }),
   109	  ]);
   110	
   111	  return { subject: subjectFor(template, props), html, text };
   112	}
