    19	 * Both sides must agree — never re-implement a strategy at a call site.
    20	 */
    21	export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
    22	  const definition = FEATURE_FLAG_DEFINITIONS[flag];
    23	  if (!definition) return false;
    24	
    25	  if (definition.overridable && ctx.overrides?.includes(flag)) {
    26	    return true;
    27	  }
