     1	import type {
     2	  EventHandler,
     3	  TaskflowEventMap,
     4	  TaskflowEventPayload,
     5	  TaskflowEventType,
     6	  Unsubscribe,
     7	} from "@/types/event";
     8	
     9	/**
    10	 * In-process, typed publish/subscribe bus.
    11	 *
    12	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
    13	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
    14	 * every reactive concern `subscribe()`s at module init (see
    15	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
    16	 * throwing handler never fails the emit or the sibling handlers.
    17	 */
    18	
    19	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
    20	
    21	const handlers = new Map<TaskflowEventType, HandlerSet>();
    22	
    23	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
    24	
    25	/** Registers a handler for one event type. Call the return value to detach. */
    26	export function subscribe<K extends TaskflowEventType>(
    27	  type: K,
    28	  handler: EventHandler<K>,
    29	): Unsubscribe {
    30	  const set = handlers.get(type) ?? new Set();
    31	  set.add(handler as EventHandler<TaskflowEventType>);
    32	  handlers.set(type, set);
    33	  return () => {
    34	    set.delete(handler as EventHandler<TaskflowEventType>);
    35	  };
    36	}
    37	
    38	/** Registers a handler that detaches itself after the first delivery. */
    39	export function subscribeOnce<K extends TaskflowEventType>(
    40	  type: K,
    41	  handler: EventHandler<K>,
    42	): Unsubscribe {
    43	  const off = subscribe(type, (payload) => {
    44	    off();
    45	    return handler(payload);
    46	  });
    47	  return off;
    48	}
    49	
    50	/**
    51	 * Publishes an event to every subscriber. Resolves once all handlers settle;
    52	 * rejected handlers are reported to the error sinks, never rethrown.
    53	 */
    54	export async function emit<K extends TaskflowEventType>(
    55	  type: K,
    56	  payload: TaskflowEventPayload<K>,
    57	): Promise<void> {
    58	  const set = handlers.get(type);
    59	  if (!set || set.size === 0) return;
    60	
    61	  const results = await Promise.allSettled(
    62	    [...set].map(async (handler) => {
    63	      await (handler as EventHandler<K>)(payload);
    64	    }),
    65	  );
    66	
    67	  for (const result of results) {
    68	    if (result.status === "rejected") {
    69	      reportHandlerError(type, result.reason);
    70	    }
    71	  }
    72	}
    73	
    74	/** Fire-and-forget variant for call sites that must not await delivery. */
    75	export function emitAndForget<K extends TaskflowEventType>(
    76	  type: K,
    77	  payload: TaskflowEventPayload<K>,
    78	): void {
    79	  void emit(type, payload).catch((error: unknown) => {
    80	    reportHandlerError(type, error);
    81	  });
    82	}
    83	
    84	export function onHandlerError(
    85	  sink: (type: TaskflowEventType, error: unknown) => void,
    86	): Unsubscribe {
    87	  errorSinks.add(sink);
    88	  return () => {
    89	    errorSinks.delete(sink);
    90	  };
    91	}
    92	
    93	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
    94	  for (const sink of errorSinks) {
    95	    try {
    96	      sink(type, error);
    97	    } catch {
    98	      // A failing error sink must never escalate.
    99	    }
   100	  }
   101	}
   102	
   103	/** Number of live subscribers for an event; used by tests and diagnostics. */
   104	export function subscriberCount(type: TaskflowEventType): number {
   105	  return handlers.get(type)?.size ?? 0;
   106	}
   107	
   108	/** Detaches every handler. Test-only — never call from application code. */
   109	export function resetEventBus(): void {
   110	  handlers.clear();
   111	  errorSinks.clear();
   112	}
   113	
   114	export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };

